for f in ['mes_03/lalur.json','mes_03/memoria.md','mes_03/ajustes.json']:
    t=open(f).read()
    for line in t.splitlines():
        if re.search(r'(status|PRELIMINAR|sessão 6|sessões 3 e 6|aguardand|pergunta aberta)', line, re.I):
            print(f, '::', line.strip()[:220]); break
print('---- stale phrases (should be none outside historical context) ----')
for f in sorted(glob.glob('**/*.md', recursive=True))+sorted(glob.glob('**/*.json', recursive=True)):
    t=open(f).read()
    for m in re.finditer(r'.{0,60}(pergunta(s)? aberta|aguardando o cliente|será perguntado novamente).{0,60}', t, re.I):
        print(f, '::', m.group(0).replace('\n',' ')[:150])
print('---- key figures present everywhere they should ----')
keys=['339.196,20','78.799,05','30.527,66','754.630,20','161.024,00','79.883,00','81.141,00','484.566,00','145.369,80']
for f in ['STATUS.md','RELATORIO_FINAL.md','mes_03/pendencias.md','mes_03/ajustes.json','mes_03/pis_cofins.json']:
    t=open(f).read()
    missing=[k for k in keys if k not in t]
    print(f, 'missing:', missing if missing else 'none')
print('ALL_JSON_OK' if ok else 'JSON_ERRORS')
EOF

